import{_ as o,o as a,c as i,a2 as n}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0056 — Applicazioni: pagine web registrate nel vault, in una vista nativa sovrapposta alla scheda (M18, traccia E)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0056-applicazioni-in-vista-nativa.md","filePath":"adr/0056-applicazioni-in-vista-nativa.md"}'),t={name:"adr/0056-applicazioni-in-vista-nativa.md"};function r(c,e,s,l,d,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0056-—-applicazioni-pagine-web-registrate-nel-vault-in-una-vista-nativa-sovrapposta-alla-scheda-m18-traccia-e" tabindex="-1">ADR-0056 — Applicazioni: pagine web registrate nel vault, in una vista nativa sovrapposta alla scheda (M18, traccia E) <a class="header-anchor" href="#adr-0056-—-applicazioni-pagine-web-registrate-nel-vault-in-una-vista-nativa-sovrapposta-alla-scheda-m18-traccia-e" aria-label="Permalink to &quot;ADR-0056 — Applicazioni: pagine web registrate nel vault, in una vista nativa sovrapposta alla scheda (M18, traccia E)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata il 2026-11-15 (decisione dell&#39;owner); implementata e rilasciata con la 1.7.0, con <code>features.web_viewer</code> <strong>spento di default</strong>: l&#39;owner ha deciso che resta spento anche nella 1.7.1, perché la matrice manuale <a href="./../qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a> non è eseguita. Dalla 1.7.2 il default di <code>features.web_viewer</code> è <strong>acceso</strong>, per <a href="./0060-web-viewer-acceso-di-default.html">ADR-0060</a> (accettata il 2026-11-16)</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.6 (2026-11-15): §0.3 (A-01), §2.2.1, §2.6.6, §3.4.5, §3.7, §4.2, Appendice B, C.2 e C.4</td></tr><tr><td><strong>Data</strong></td><td>2026-11-15</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (riga «Web viewer», P2: «Limitato: molti siti bloccano l&#39;incorniciamento; valutare pannello nativo», <code>Specifications.md:366</code>; riga «Finestre separate (pop-out)», P2, <code>:351</code>), §0.2 V-02 (<code>:54</code>) e D-01 (<code>:1914</code>), §0.3 A-03 (<code>:68</code>), §2.6.6 (feature flag «Web viewer», <code>:599</code>), §3.7 (righe «Contenuti» e «Web UI», CSP, <code>:1512-1513</code>), Appendice B (post-1.0, <code>:1904</code>), C.2 (rischi «Web viewer in iframe bloccato da <code>X-Frame-Options</code>», <code>:1935</code>, e «Limiti di Wails v2», <code>:1944</code>); V-07 e D-07 (Wails, ADR-0051); ADR-0029 e ADR-0030 (workbench web e core WASM), ADR-0037 e ADR-0045 (registro delle funzioni e parità), ADR-0047 (apertura dei file per tipo)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>in un punto:</strong> anticipa il Web viewer da P2/post-1.0 a M18 (1.7.0) e sceglie la «webview nativa» che lo spec lasciava da valutare; per il resto è un&#39;aggiunta. <strong>Non</strong> tocca «una sola finestra» (la vista è figlia della stessa finestra), né V-02/D-01 (nessun plugin, nessun CSS personalizzato, la pagina ospite non ha alcun ponte verso l&#39;app), né la CSP. Da integrare: §2.2.1 (riga Web viewer), Appendice B, C.2, §2.6.6, §3.7, §4.2, C.4 e l&#39;elenco dei formati del vault (<code>.webapp</code>). Elenco puntuale in «Sezioni dello spec da aggiornare» in fondo</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (prove: <code>internal/webview</code> <code>manager_test.go</code>, <code>url_test.go</code>, <code>accelerator_test.go</code>; <code>internal/app/bindings_webview_test.go</code>, <code>internal/app/webviews_sweep_test.go</code>, <code>internal/links/links_test.go</code> e <code>internal/app/bindings_suggest_test.go</code> per il selettore rapido, <code>winpure_test.go</code> e <code>driver_windows_test.go</code> per il driver Windows spento; vitest in <code>packages/workbench/src/webapp/</code> e <code>commands/QuickSwitcher.test.tsx</code>; e2e <code>apps/desktop/frontend/e2e/webapp.spec.ts</code> e <code>quick-switcher.spec.ts</code> sul mock dei binding; a11y in <code>a11y.spec.ts</code>; <strong>driver macOS: <code>driver_darwin_live_test.go</code>, a mano con <code>task test-nativeview</code></strong>) · workbench web (voce <code>webapp</code>: sì, con lo stesso <code>webapp.spec.ts</code> sul core WASM per ciò che non richiede la vista incorporata; voce <code>webapp.embedded</code>: <strong>eccezione</strong>, la pagina si apre in una scheda del browser e <code>WebViewAPI</code> risponde <code>webview-unavailable</code>) · console: non applicabile · cloud: solo la descrizione di <code>features.web_viewer</code> nello schema del Config Profile; nessuna modifica di API, database o sync. Registro: voci <code>webapp</code> e <code>webapp.embedded</code> di <code>shared/parity/features.yaml</code>. <strong>Non provato sulla finestra reale del desktop</strong> per ciò che riguarda il frontend (vedi «Cosa resta da verificare»)</td></tr></tbody></table><blockquote><p><strong>Nota (M21, 2026-11-16).</strong> <a href="./0060-web-viewer-acceso-di-default.html">ADR-0060</a>, <strong>accettata</strong> il 2026-11-16 per decisione dell&#39;owner, <strong>cambia il default di <code>features.web_viewer</code> da spento ad acceso</strong> (dalla 1.7.2) e aggiunge «Nuova applicazione» nell&#39;esploratore dei file. Questo testo descrive la decisione com&#39;era alla 1.7.1 ed è lo storico: la riga «Stato», il punto 6, la sezione «Cosa resta da verificare» e le conseguenze che dicono «spento di default» vanno lette con il nuovo default. Lo spec v1.6 dice ancora «spento»: lo cambia la v1.7 (<a href="./../spec-v1.7-proposta.html"><code>spec-v1.7-proposta.md</code></a>).</p></blockquote><blockquote><p><strong>Nota (M22, 2026-11-20).</strong> <a href="./0062-vista-integrata-windows-linux.html">ADR-0062</a>, <strong>accettata</strong> il 2026-11-20 (recepita in <code>Specifications.md</code> v1.8, 2026-11-20; <a href="./../spec-v1.8-proposta.html"><code>../spec-v1.8-proposta.md</code></a> resta come storia), emenda i punti 2, 17 e 34-36 e l&#39;alternativa «Un driver GTK per Linux»: dalla 1.7.3 la vista integrata è accesa di default anche su Windows (driver WebView2, senza l&#39;interruttore <code>CLARAE_WEBVIEW2_EXPERIMENTAL</code>, sostituito da <code>CLARAE_WEBVIEW=off</code>) e su Linux (nuovo driver WebKitGTK), con ripiego automatico a «Apri nel browser» se driver o runtime falliscono. Questo testo resta lo storico della decisione com&#39;era alla 1.7.1: i punti 34-36 (driver Windows «spento», <code>CLARAE_WEBVIEW2_EXPERIMENTAL</code>, capability solo macOS) e la sottosezione «Driver sperimentale (interruttore)» della matrice descrivono la 1.7.1.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Lo spec mette il Web viewer in P2 con una riga di avvertimento: «molti siti bloccano l&#39;incorniciamento; valutare pannello nativo» (§2.2.1, <code>Specifications.md:366</code>), e lo ripete tra i rischi («Web viewer in iframe bloccato da <code>X-Frame-Options</code>», C.2, <code>:1935</code>: «funzione P2 con limitazioni dichiarate o webview nativa dedicata») e nel post-1.0 (Appendice B, <code>:1904</code>). Il vincolo di Wails è che la finestra è una sola e le finestre separate (pop-out) restano P2 (A-03, <code>:68</code>; riga «Finestre separate», <code>:351</code>). L&#39;architettura è chiusa: niente plugin, temi o CSS personalizzato (V-02/D-01, <code>:54</code> e <code>:1914</code>).</p><p>Per M18 il proprietario ha chiesto di anticipare la funzione: una <strong>applicazione</strong> è un indirizzo registrato che si apre in un browser interno dentro una scheda. Il flag <code>features.web_viewer</code> esisteva già nello schema del Config Profile, «riservato», spento e senza effetti (§2.6.6, <code>:599</code>).</p><p>Un <code>&lt;iframe&gt;</code> non è una strada: la CSP del client ha <code>frame-src &#39;none&#39;</code> (<code>apps/desktop/internal/app/csp_prod.go:15</code>, <code>csp_dev.go:14</code>, verificata da <code>csp_test.go</code>) e molti siti vietano comunque di essere incorniciati (<code>X-Frame-Options</code>, <code>frame-ancestors</code>). Serve una vista del sistema, separata dalla pagina dell&#39;app.</p><p>Prima di costruire, lo spike E0 (un programma usa-e-getta, solo API pubbliche di Wails: <code>NativeWindow()</code> e <code>InvokeSync</code>; non fuso nel prodotto) ha dato questo esito per sistema: <strong>macOS sì</strong> (eseguito: un sito con <code>X-Frame-Options: DENY</code> caricato, bounds entro 1 pt, isolamento, scorciatoie riservate, 200 cicli di apertura e chiusura senza crash); <strong>Windows sì, a condizione</strong> di una copia ridotta del binding WebView2 interno di Wails (compilato, mai eseguito; stima di 4-6 giorni); <strong>Linux no per ora</strong> (compilato in un container, mai eseguito). I log dello spike non sono conservati: le sue misure sono state ripetute dalla prova del driver (<code>task test-nativeview</code>, vedi «Verifiche eseguite»).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="decisioni-del-proprietario" tabindex="-1">Decisioni del proprietario <a class="header-anchor" href="#decisioni-del-proprietario" aria-label="Permalink to &quot;Decisioni del proprietario&quot;">​</a></h3><ol><li><strong>Webview nativa sovrapposta alla scheda, solo desktop.</strong> Sul web (workbench) l&#39;applicazione si apre in una scheda del browser.</li><li><strong>Il driver acceso c&#39;è solo su macOS.</strong> Su Windows e Linux la capability <code>embeddedBrowser</code> è spenta e l&#39;applicazione si apre nel browser di sistema. <strong>Dalla 1.7.1</strong> il driver di Windows è nel prodotto, compilato ma <strong>spento</strong> finché non è provato su una macchina Windows (punti 34-36); la capability resta solo macOS.</li><li><strong>User agent simile a Safari</strong> (<code>Version/18.0 Safari/605.1.15</code> aggiunto al nome dell&#39;applicazione, <code>guest_darwin.m</code>): una vista nuova che non si presenta come un browser noto è trattata peggio da alcuni siti.</li><li><strong>Schede in secondo piano: la vista nascosta non si tiene viva.</strong> Il motore web rallenta i suoi timer (misurato nello spike E0); chat e riproduzione in una scheda non attiva ne risentono, ed è accettato.</li><li><strong>Sessioni persistenti per vault, locali al dispositivo, fuori dal vault.</strong></li><li><strong>La 1.7.0 include la traccia E.</strong> Il flag resta spento di default finché la matrice manuale non è eseguita.</li></ol><h3 id="modello-il-file-webapp" tabindex="-1">Modello: il file <code>.webapp</code> <a class="header-anchor" href="#modello-il-file-webapp" aria-label="Permalink to &quot;Modello: il file `.webapp`&quot;">​</a></h3><ol start="7"><li><strong>Un&#39;applicazione è un file <code>.webapp</code> del vault</strong>, <code>{&quot;version&quot;:1,&quot;url&quot;:&quot;https://…&quot;}</code> (<code>webapp/model.ts</code>). È un file come gli altri: si rinomina, si elimina, si segnala, si sincronizza, ricompare con il layout. Per la sync è di tipo <code>other</code> (<code>syncproto.KindOf</code>): modificato su due dispositivi vale l&#39;ultima scrittura se è lo stesso utente, altrimenti nasce una copia di conflitto (<code>merge/policy.go</code>, D-04).</li><li><strong>Lettura tollerante, indirizzo severo.</strong> <code>parseWebapp</code> ignora un BOM, i campi sconosciuti e un <code>version</code> mancante; rifiuta una versione diversa da 1 e ogni indirizzo che non sia <strong>http o https assoluto, con host, senza credenziali, senza caratteri di controllo, spazi o barre rovesciate, di al massimo 16 KiB</strong> (<code>checkWebappUrl</code>). Le stesse regole sono nel core Go (<code>webview.ValidateURL</code>, <code>url.go</code>), che le ricontrolla a ogni apertura e a ogni navigazione. Un indirizzo digitato senza schema riceve <code>https://</code> (<code>completeUrl</code>).</li><li><strong>Il selettore rapido trova i <code>.webapp</code></strong> (dalla 1.7.1; nella 1.7.0 cercava solo le note). <code>LinksAPI.Suggest</code> con <code>kind = &#39;all&#39;</code> usa <code>links.SuggestFiles</code> (<code>apps/desktop/internal/links/suggest.go</code>): le note, le presentazioni e gli alias di prima, più i file che l&#39;app apre in una scheda e che non sono Markdown, cioè applicazioni, lavagne, basi e disegni, per nome senza estensione e per percorso. Un <code>.webapp</code> non ha un tipo suo nell&#39;indice (è <code>other</code>) e si riconosce dall&#39;estensione: non entra ogni file <code>other</code>. L&#39;UI (<code>commands/QuickSwitcher.tsx</code>) mostra l&#39;icona del tipo e fa leggere ai lettori di schermo il tipo accanto al nome (<code>switcher.kind.*</code>); il file si apre come dall&#39;esploratore (<code>openNote</code>, ciascun tipo nella sua vista), quindi un <code>.webapp</code> passa dalla conferma dell&#39;origine (punto 11). I suggerimenti dei wikilink e i selettori di nota (<code>kind = &#39;notes&#39;</code>) sono <strong>invariati</strong>: solo note. Un file di un altro tipo con lo stesso nome non nasconde più «Crea nota», e nemmeno un titolo: la creazione sparisce solo se esiste già una nota, una presentazione <code>.marp</code> o un alias con quel nome (crearne una omonima riassegnerebbe i link esistenti): lavagne, basi, disegni, applicazioni e titoli non la tolgono. <strong>I file in <code>.trash/</code> e nelle cartelle nascoste</strong> (un segmento del percorso che inizia con <code>.</code>) <strong>non compaiono</strong> né nel selettore né nei suggerimenti dei wikilink e del selettore di note dei disegni, come nell&#39;esploratore dei file (nella 1.7.0 le note nel cestino comparivano nei suggerimenti). <code>app:open</code> elenca ancora le sole applicazioni. Un <code>.webapp</code> incorporato in una nota (<code>![[x.webapp]]</code>) non carica nulla: mostra un avviso (<code>embeds/hydrate.ts</code>).</li><li><strong>Comandi</strong> (<code>commands/registry.ts</code>). Voce <code>webapp</code> (senza capability): <code>app:new</code>, <code>app:open</code>, <code>app:edit-url</code>, <code>app:open-in-browser</code>. Voce <code>webapp.embedded</code> (richiedono <code>embeddedBrowser</code>): <code>app:back</code> (<code>Mod-[</code>), <code>app:forward</code> (<code>Mod-]</code>), <code>app:reload</code> (<code>Mod-r</code>), <code>app:clear-data</code>. <code>app:new</code> è nel ribbon e nello stato vuoto (traccia B), nascosto con il flag spento; creazione e modifica sono disabilitate su un vault in sola lettura.</li><li><strong>Conferma alla prima apertura di un&#39;origine</strong> su questo dispositivo, per vault (<code>webapp/origins.ts</code>, <code>localStorage</code>, chiave <code>clarae.webapp.origins.&lt;vaultId&gt;</code>), <strong>anche per chi ha appena creato l&#39;applicazione</strong>: il file può arrivare dalla sync o da un altro utente di un vault condiviso, quindi non carica una pagina solo perché esiste. La conferma riguarda l&#39;origine registrata nel file; dentro la pagina si naviga dove la pagina porta. <code>app:clear-data</code> azzera le conferme.</li><li><strong>L&#39;indirizzo nella barra è solo testo.</strong> Per cambiarlo ci sono «Cambia indirizzo» e <code>app:edit-url</code>, che riscrivono il file (con l&#39;hash letto: una modifica concorrente è un conflitto, non una sovrascrittura). Un campo digitabile sarebbe una seconda via per andare ovunque, che salterebbe la conferma.</li><li><strong>Ripiego.</strong> Senza la capability (web, Windows, Linux), con il flag spento o su errore <code>webview-unavailable</code>/<code>webview-disabled</code>, la scheda è un riquadro con il pulsante «Apri nel browser» (browser di sistema sul desktop, nuova scheda sul web). Nessun <code>&lt;iframe&gt;</code>, in nessun caso.</li></ol><h3 id="il-core-un-gestore-unico-delle-viste" tabindex="-1">Il core: un gestore unico delle viste <a class="header-anchor" href="#il-core-un-gestore-unico-delle-viste" aria-label="Permalink to &quot;Il core: un gestore unico delle viste&quot;">​</a></h3><ol start="14"><li><strong><code>internal/webview</code></strong> (piattaforma-indipendente): <code>Driver</code> (interfaccia), <code>Manager</code>, <code>Fake</code> (per i test), <code>ValidateURL</code>/<code>Inspect</code>, <code>ParseAccelerator</code>, eventi. Il <code>Manager</code> possiede le viste, le attribuisce al vault, applica i limiti e la politica di navigazione, e <strong>non apre mai una vista di sua iniziativa</strong>: la scheda restaurata con il layout non carica nulla finché la UI non chiama <code>Open</code>.</li><li><strong>Binding <code>WebViewAPI</code></strong> (<code>internal/app/bindings_webview.go</code>), 13 metodi: <code>Status</code>, <code>Open</code>, <code>SetBounds</code>, <code>SetVisible</code>, <code>Navigate</code>, <code>Back</code>, <code>Forward</code>, <code>Reload</code>, <code>Focus</code>, <code>Close</code>, <code>CloseVault</code>, <code>ReserveKeys</code>, <code>ClearData</code>. Ogni chiamata che nomina una vista nomina anche il vault; un vault non aperto o un vault privato bloccato è rifiutato. Errori <code>webview-*</code> (<code>ErrCodeWebView*</code>: <code>unavailable</code>, <code>disabled</code>, <code>invalid-url</code>, <code>invalid-bounds</code>, <code>not-found</code>, <code>limit</code>, <code>failed</code>, <code>invalid-accelerator</code>). <strong>Sul core WASM ogni metodo risponde <code>webview-unavailable</code></strong>: il <code>Manager</code> non è compilato per <code>js</code>.</li><li><strong>Eventi</strong> (<code>internal/events</code>, generati in <code>events.gen.ts</code>): <code>webview:state</code>, <code>webview:blocked</code>, <code>webview:new-window</code>, <code>webview:download</code>, <code>webview:permission</code>, <code>webview:key</code>, <code>webview:load-error</code>, <code>webview:crashed</code>, <code>webview:focus</code>, <code>webview:closed</code>. I testi che arrivano da una pagina (indirizzo, titolo, messaggio) sono mostrati solo come testo, mai come markup.</li><li><strong>Capability <code>embeddedBrowser</code></strong> (<code>capabilities.go</code>): vera solo sul desktop <strong>su macOS con il driver</strong>; falsa su Windows, Linux e web. La tabella dichiara «desktop» con <code>DesktopOS: {&quot;darwin&quot;}</code>, il core restringe la colonna al sistema su cui gira (<code>platformCapabilities</code>) e <code>SettingsAPI.Capabilities()</code> la spegne ancora se il driver manca (build senza cgo, finestra non creata). <strong>Servono entrambe, capability e flag:</strong> il core rifiuta <code>Open</code> senza <code>features.web_viewer</code> e <strong>chiude le viste</strong> se un profilo nuovo lo spegne (<code>applyWebViewFlag</code>, <code>webview:closed</code> con motivo <code>disabled</code>).</li><li><strong>Limiti:</strong> 32 viste per vault e 64 in tutto (<code>MaxViewsPerVault</code>, <code>MaxViewsTotal</code>): una vista è un processo e qualche centinaio di megabyte, i numeri sono molto sopra l&#39;uso reale e fermano un ciclo della UI.</li><li><strong>Ciclo di vita.</strong> Le viste di un vault si chiudono alla chiusura del vault, alla rimozione di un mount, al blocco di un vault privato (manuale, per inattività o dalla sync) e all&#39;uscita (<code>Shutdown</code>). <strong>L&#39;attività dentro un&#39;applicazione conta come attività</strong> per il blocco automatico di un vault privato: il puntatore e i tasti non arrivano alla web view dell&#39;app, che è ciò che il timer ascolta (<code>OnActivity</code>).</li></ol><h3 id="il-driver-macos" tabindex="-1">Il driver macOS <a class="header-anchor" href="#il-driver-macos" aria-label="Permalink to &quot;Il driver macOS&quot;">​</a></h3><ol start="20"><li><strong><code>internal/shell/nativeview</code></strong> (cgo, Objective-C, <code>guest_darwin.m</code>): un <code>WKWebView</code> aggiunto come <strong>figlio della content view della stessa finestra</strong>, sopra la web view dell&#39;app (<code>addSubview:positioned:NSWindowAbove</code>), con le sole API pubbliche di Wails (<code>NativeWindow()</code>, <code>InvokeSync</code>) e nulla di patchato. <strong>Non esiste una finestra secondaria</strong>: il vincolo di una sola finestra per processo resta com&#39;è. Altrove <code>New</code> restituisce <code>nil</code> (<code>driver_other.go</code>).</li><li><strong>Bounds come frazioni (0..1) del viewport</strong>, origine in alto a sinistra: la UI misura il rettangolo del segnaposto e invia i rapporti, quindi il numero non dipende dal rapporto di pixel né dallo zoom dell&#39;app. Il core rifiuta valori fuori dall&#39;intervallo (<code>webview-invalid-bounds</code>) e tronca gli errori di arrotondamento.</li></ol><h3 id="il-frontend-una-vista-nativa-sta-sempre-sopra-l-html" tabindex="-1">Il frontend: una vista nativa sta sempre sopra l&#39;HTML <a class="header-anchor" href="#il-frontend-una-vista-nativa-sta-sempre-sopra-l-html" aria-label="Permalink to &quot;Il frontend: una vista nativa sta sempre sopra l&#39;HTML&quot;">​</a></h3><ol start="22"><li><strong><code>webapp/nativeViews.ts</code> è l&#39;unico punto che apre, muove e chiude le viste</strong>: ogni chiamata di <code>WebViewAPI</code> che nomina una vista passa da lì (l&#39;unica chiamata fuori dal gestore è <code>ClearData</code>, che agisce sul vault, dal comando <code>app:clear-data</code> in <code>webapp/commands.ts</code>). Ogni scheda di applicazione mostra una barra (indietro, avanti, ricarica, indirizzo, «Cambia indirizzo», «Apri nel browser») e un segnaposto vuoto che dà alla vista il suo rettangolo (ResizeObserver, ridimensionamento della finestra, scorrimento e ogni cambio di layout, al più una volta per fotogramma).</li><li><strong>La vista si nasconde</strong> (la pagina resta, <code>SetVisible(false)</code>) per soppressione esplicita (trascinamento di una scheda, di uno splitter o di un file; scheda non attiva) e quando qualcosa dell&#39;app è disegnato sopra il segnaposto, che una <strong>sonda <code>elementsFromPoint</code> a griglia</strong> (9 × 7 punti) trova senza modificare palette, menu, dialoghi, tooltip. <strong>Limite:</strong> un overlay molto più piccolo del passo della griglia (circa un nono della larghezza) e senza sfondo può passare tra i punti.</li><li><strong>Una vista appartiene a una scheda.</strong> Cambiare scheda la nasconde e conserva la pagina; chiudere la scheda la chiude; due pannelli sulla stessa applicazione sono due viste. Una scheda ripristinata con il layout non apre nulla finché il suo segnaposto non è mostrato e libero.</li><li><strong>Scorciatoie.</strong> Una pagina con il fuoco riceve ogni tasto, quindi le hotkey dei comandi dell&#39;app (esclusi quelli dell&#39;editor e <code>mode:*</code>) sono <strong>riservate</strong> (<code>ReserveKeys</code>, tradotte da <code>webapp/accelerators.ts</code> nella grammatica del core: <code>ctrl</code>, <code>alt</code>, <code>shift</code>, <code>cmd</code>, mai le scorciatoie di editing del testo) e, premute con il fuoco nella pagina, il core le restituisce con <code>webview:key</code> e la UI esegue il comando. Una combinazione che il core rifiuterebbe non è riservata: la pagina la tiene.</li></ol><h3 id="sicurezza-della-pagina-ospite" tabindex="-1">Sicurezza della pagina ospite <a class="header-anchor" href="#sicurezza-della-pagina-ospite" aria-label="Permalink to &quot;Sicurezza della pagina ospite&quot;">​</a></h3><ol start="26"><li><strong>Nessun ponte verso l&#39;app</strong> (<code>guest_darwin.m</code>): una <code>WKWebViewConfiguration</code> nuova, <strong>senza message handler, user script né scheme handler</strong>; lo schema <code>wails://</code> è registrato solo sulla web view dell&#39;app, quindi l&#39;origine dell&#39;app, i binding e gli eventi non sono raggiungibili dalla pagina. La CSP dell&#39;app <strong>non cambia</strong> e non c&#39;è nessun <code>&lt;iframe&gt;</code>.</li><li><strong>Navigazione.</strong> Nel frame principale solo <code>http</code> e <code>https</code>, validati <strong>in Go a ogni navigazione, redirect compresi</strong> (<code>Manager.policy</code>); un indirizzo con credenziali è rifiutato. Nei frame dentro la pagina, anche <code>about</code>, <code>blob</code> e <code>data</code> (ciò che le pagine usano per costruire i frame).</li><li><strong>Download rifiutati</strong>, prima che scrivano qualcosa. <strong>Permessi negati</strong> (camera e microfono, sensori di movimento, accesso allo storage, scelta di file); ogni rifiuto è un avviso nella scheda. Per posizione e notifiche la prova del driver verifica che non vengano concesse. Gli <code>alert</code> della pagina sono confermati, un <code>confirm</code> risponde no e un <code>prompt</code> non risponde nulla. Ispezione spenta, nessuna favicon scaricata, nessuna voce del menu contestuale che apra finestre o scarichi.</li><li><strong>Nuove finestre.</strong> <code>window.open</code> e <code>target=_blank</code> non aprono nulla nell&#39;app. L&#39;indirizzo va al <strong>browser di sistema</strong> solo se è valido, solo dopo <strong>un gesto recente dell&#39;utente nella vista</strong>, <strong>mai da una vista nascosta</strong>, e al massimo <strong>uno al secondo</strong> (<code>newWindow</code>).</li><li><strong>Certificati.</strong> Un errore di certificato fa fallire il caricamento, <strong>senza modo di proseguire</strong> (la scheda mostra l&#39;errore e «Apri nel browser»).</li><li><strong>Autenticazione HTTP non supportata.</strong> Le richieste di credenziali (Basic, Digest, NTLM, Negotiate, certificato client) sono <strong>annullate</strong>: il trattamento di sistema offrirebbe a un server scelto dalla pagina ciò che il sistema custodisce (una password del portachiavi, un&#39;identità). <strong>I login che usano un popup con <code>window.opener</code> non funzionano</strong>: i popup vanno al browser di sistema.</li><li><strong>Rete privata.</strong> L&#39;utente può aprire un indirizzo privato o di loopback (gli strumenti self-hosted sono lo scopo delle applicazioni): <code>localhost</code>, <code>*.localhost</code>, <code>*.local</code>, <code>*.lan</code>, <code>*.internal</code>, <code>*.home.arpa</code>, un nome a etichetta singola, e gli indirizzi di loopback, privati, link-local e non specificati (anche in forma IPv6 di un IPv4 privato). Ma <strong>una pagina raggiunta da un sito pubblico non può portare la vista su loopback o rete locale</strong>: sono lì i servizi locali e il listener di loopback dell&#39;accesso OIDC (D-08). La regola vale per il frame principale e per le nuove finestre; <strong>non</strong> per ciò che una pagina incorpora in un frame o richiede con <code>fetch</code>. <strong>I nomi non vengono risolti: il DNS rebinding non è coperto.</strong> Una pagina aperta su un host privato può andare ad altri host privati; una navigazione dell&#39;utente verso un host pubblico svuota l&#39;insieme degli host privati scelti.</li><li><strong>Dati di sessione.</strong> Un <code>WKWebsiteDataStore</code> <strong>per vault</strong>, con un identificatore casuale (UUID) tenuto in <code>app.db</code> (<code>app_settings</code>, chiave <code>webview_store:&lt;vaultId&gt;</code>): <strong>non nel vault, non sincronizzato, non derivato dal percorso del vault</strong> (un altro vault aperto più tardi allo stesso percorso non eredita i cookie del precedente). I dati stanno nel contenitore di WebKit, <strong>non</strong> in <code>&lt;dataDir&gt;/webapps/…</code> come prevedeva il piano: <code>WKWebView</code> non permette di scegliere la cartella (<strong>deviazione dal piano</strong>). <strong>Prima di macOS 14 lo store non è persistente</strong> (<code>dataStoreForIdentifier</code> è di macOS 14): la sessione dura quanto l&#39;app, e l&#39;app supporta macOS 13 (<code>LSMinimumSystemVersion</code> 13.0.0). <code>ClearData</code> chiude le viste del vault e cancella i dati delle sue applicazioni su questo dispositivo; alla rimozione di un mount i dati vengono cancellati e l&#39;identificatore dimenticato. La cartella di un vault eliminata fuori dall&#39;app non può essere segnalata all&#39;app: se ne occupa la <strong>pulizia in background</strong> (1.7.1, <code>apps/desktop/internal/app/webviews_sweep.go</code>), che parte dopo l&#39;avvio senza farlo attendere (aspetta fino a 2 minuti che esista la finestra, e con essa il driver; altrimenti non fa nulla fino all&#39;avvio successivo). Cancella i dati e la riga di <code>app_settings</code> <strong>solo</strong> per un vault che non è aperto né in apertura, non è un mount (una cartella nella cartella dei mount dell&#39;app) e, se compare tra i recenti, è «sicuramente sparito»: aperto l&#39;ultima volta più di 30 giorni prima (<code>webviewStoreGrace</code>), non su un volume rimovibile (su Windows un disco diverso da quello di sistema o una condivisione di rete; altrove <code>/Volumes</code>, <code>/media</code>, <code>/mnt</code> e simili), con la cartella che risponde «non esiste» (non «accesso negato» né un errore di I/O) mentre la cartella che la contiene c&#39;è, si legge e <strong>non è vuota</strong>: una madre vuota è la firma di un punto di mount scelto dall&#39;utente e non montato (rclone, sshfs, macFUSE, Cryptomator), e il vault si tiene. <strong>Limite noto:</strong> un vault cancellato che era l&#39;unica cosa nella sua cartella lascia un orfano di qualche megabyte. Subito prima di cancellare si ricontrolla che il vault non sia stato aperto nel frattempo <strong>Mai</strong> per un vault solo chiuso o su un disco non montato: tenere l&#39;archivio di un vault sparito costa pochi megabyte di cookie, cancellare quello di un vault che esiste disconnette l&#39;utente dai siti. Una riga il cui vault non compare da nessuna parte (neppure tra i recenti) si cancella senza il periodo. I dati della piattaforma vanno per primi e la riga dopo: se la piattaforma fallisce la riga resta e si riprova all&#39;avvio successivo; dove non c&#39;è un driver vanno solo le righe. Fino alla pulizia lo stesso percorso riusa l&#39;identificatore, o lo cancella <code>ClearData</code>. <strong>La deviazione dal piano</strong> (dati nel contenitore di WebKit e non in <code>&lt;dataDir&gt;/webapps/…</code>) <strong>resta e con la pulizia è accettata.</strong></li></ol><h3 id="il-driver-windows-compilato-e-spento-1-7-1" tabindex="-1">Il driver Windows: compilato e spento (1.7.1) <a class="header-anchor" href="#il-driver-windows-compilato-e-spento-1-7-1" aria-label="Permalink to &quot;Il driver Windows: compilato e spento (1.7.1)&quot;">​</a></h3><ol start="34"><li><strong>Che cosa c&#39;è.</strong> <code>internal/shell/nativeview</code> ha un driver per Windows (<code>driver_windows.go</code>, <code>guest_windows.go</code>, <code>winapi_windows.go</code>, la parte senza chiamate di sistema in <code>winpure.go</code>) sopra una <strong>copia ridotta e corretta del binding WebView2 interno di Wails v3.1.0</strong> (<code>webview2/</code>, con <code>LICENSE</code> e <code>NOTICE</code> che dicono licenza e provenienza di ogni parte e quali correzioni sono state fatte). È un secondo controller WebView2 sulla finestra, con un ambiente e una cartella dati propri per ogni vault (quindi un processo del browser per vault), in <code>&lt;dataDir&gt;\\webapps\\&lt;store&gt;</code>. Come su macOS non c&#39;è alcun ponte verso l&#39;app: il bridge di Wails non è iniettato, i messaggi web sono spenti, nessun host object né script. Compila per amd64 e arm64 con CGO spento, e <code>task ci</code> lo compila a ogni esecuzione con il passo <code>vet-windows</code> (<code>go vet</code>, compilazione dei test senza eseguirli e golangci-lint, per le due architetture): il codice non gira su un Mac, ma non si rompe senza che nessuno se ne accorga.</li><li><strong>Spento.</strong> Non è mai stato eseguito su Windows; la revisione della 1.7.1 ha verificato che è davvero spento. Si accende solo con la variabile d&#39;ambiente <code>CLARAE_WEBVIEW2_EXPERIMENTAL=1</code> (vale il solo valore <code>1</code>); senza, <code>New</code> restituisce <code>nil</code> come sugli altri sistemi senza driver. <strong>Anche acceso, la capability <code>embeddedBrowser</code> resta solo macOS</strong> (<code>DesktopOS</code> in <code>internal/app/capabilities.go</code>): l&#39;interfaccia apre comunque le applicazioni nel browser di sistema. L&#39;interruttore serve a provare il driver su una macchina Windows. Per accenderlo davvero, quando sarà provato: <code>windows</code> in <code>DesktopOS</code>, <code>Supported</code> vero senza interruttore, <code>task gen</code>, registro di parità e guide (utente e admin).</li><li><strong>Differenze dichiarate rispetto a macOS.</strong> User agent di Edge, non simile a Safari (la scelta del punto 3 vale per macOS). Il selettore di file non si può negare (a macOS la scelta di file è negata). Per il blocco automatico di un vault privato (punto 19) contano solo i tasti e il fuoco: WebView2 non dà all&#39;host il mouse né la rotella, quindi chi legge e scorre soltanto è, per il blocco, inattivo. Il gesto dell&#39;utente per le nuove finestre viene da <code>IsUserInitiated</code>. L&#39;autenticazione integrata di Windows (NTLM, Kerberos) è gestita dal runtime e non dal driver; Basic e il certificato client sono annullati. Il runtime WebView2 deve essere almeno 1.0.2210.55: con uno più vecchio la vista è rifiutata (non gira una vista con meno protezioni) e la pagina si apre nel browser di sistema. Le prove da fare su Windows sono la sottosezione «Driver sperimentale (interruttore)» della matrice <a href="./../qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a>.</li></ol><h3 id="revisione-di-sicurezza-del-core" tabindex="-1">Revisione di sicurezza del core <a class="header-anchor" href="#revisione-di-sicurezza-del-core" aria-label="Permalink to &quot;Revisione di sicurezza del core&quot;">​</a></h3><p>Una revisione di sicurezza del core ha trovato <strong>otto rilievi, tutti corretti con un test ciascuno</strong>. I due confermati: la regola della rete privata restava «accesa» per tutta la vita di una vista aperta su un host privato (ora dipende dalla pagina corrente e dagli host scelti dall&#39;utente); una vista aperta mentre il vault si chiudeva restava orfana (ora <code>Open</code> ricontrolla vault e flag dopo che il sistema ha creato la vista). Gli altri: le scorciatoie riservate erano consumate solo dalla vista a fuoco; le richieste di credenziali non erano annullate; gli acceleratori con Maiusc; il ricontrollo del flag dopo l&#39;apertura; l&#39;identificatore dello store era derivato dal percorso del vault; il browser di sistema si apriva senza un gesto dell&#39;utente.</p><h3 id="verifiche-eseguite" tabindex="-1">Verifiche eseguite <a class="header-anchor" href="#verifiche-eseguite" aria-label="Permalink to &quot;Verifiche eseguite&quot;">​</a></h3><ul><li><strong>Go:</strong> test di <code>internal/webview</code>, <code>internal/app</code>, <code>internal/shell</code>, <code>internal/sync</code> con <code>-race</code>, verdi; <code>go vet</code> per <code>GOOS=js</code>, <code>GOOS=windows CGO_ENABLED=0</code> e <code>GOOS=linux</code>; <code>task lint-go</code> con 0 rilievi; <code>task test-wasm</code>; <code>task gen</code> e <code>task check-gen</code>.</li><li><strong>Prova del driver su un Mac reale</strong> (<code>task test-nativeview</code>, macOS 27.2.1, arm64): <strong>14 prove su 14</strong>, tra cui un sito che vieta l&#39;incorniciamento caricato (<code>https://github.com</code>), bounds entro il punto a più dimensioni della finestra, schemi vietati rifiutati, nuove finestre non aperte, download rifiutati, certificato autofirmato rifiutato, richieste di credenziali annullate, scorciatoie riservate, 100 cicli di apertura e chiusura, dati separati per vault e <code>ClearData</code>.</li><li><strong>Frontend:</strong> vitest del workbench, 2.475 test verdi (115 nella cartella <code>webapp</code>); <code>task lint-ts</code>; <code>task parity</code> verde (96 funzioni, 203 comandi, 155 binding); e2e <code>webapp.spec.ts</code> (17 casi) sul mock dei binding e, per ciò che non richiede la vista incorporata, sul core WASM; a11y. Quattro prove di mutazione sul frontend (indirizzo non http accettato, testo della pagina reso come markup, vista sotto un dialogo, conferma dell&#39;origine saltata) fanno fallire i test.</li><li><code>task ci</code> completo è verde con le applicazioni dentro (2026-11-15). <strong>Dopo una revisione del frontend</strong> sono stati corretti altri rilievi, ciascuno con un test: una vista che finiva di aprirsi dopo che la scheda era stata lasciata restava disegnata sopra l&#39;altra scheda; la pagina poteva prendere la tastiera da un altro pannello; un trascinamento non concluso poteva lasciare le viste nascoste; dopo il blocco del vault l&#39;applicazione non si riapriva senza chiudere la scheda; gli eventi della vista arrivati prima della risposta di <code>Open</code> andavano persi; <code>F2</code> e i comandi dell&#39;editor non sono più riservati sopra una pagina.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong><code>&lt;iframe&gt;</code></strong> — impossibile: la CSP ha <code>frame-src &#39;none&#39;</code> (aprirla toglierebbe una difesa dell&#39;app, V-02/D-01) e molti siti vietano l&#39;incorniciamento (<code>X-Frame-Options</code>, <code>frame-ancestors</code>): è il problema che lo spec segnalava. La prova del driver carica <code>https://github.com</code> in una vista nativa.</li><li><strong>Una voce in <code>.clarae/apps.json</code> al posto del file <code>.webapp</code></strong> — scartata: un elenco in un unico file di configurazione non ha rinomina, eliminazione, segnalibri né ripristino delle schede, e due dispositivi che aggiungono un&#39;applicazione nello stesso momento modificano lo stesso file; con un file per applicazione non si sovrascrivono mai.</li><li><strong>Copiare il binding WebView2 interno di Wails per Windows</strong> — <strong>scartata nella 1.7.0, adottata nella 1.7.1 come driver spento.</strong> La 1.7.0 la scartava (decisione del proprietario: driver solo macOS): l&#39;esito di E0 era «sì condizionato» a una copia ridotta di codice interno di una dipendenza (stima di 4-6 giorni), compilata e mai eseguita, con la manutenzione di una copia che Wails può cambiare. L&#39;owner ha poi deciso che il driver entra nel prodotto, compilato e <strong>spento</strong> finché non è provato su una macchina Windows (punti 34-36). Il costo resta quello della copia da tenere allineata a Wails; su Windows l&#39;applicazione continua ad aprirsi nel browser di sistema.</li><li><strong>Un driver GTK per Linux</strong> — non fatto: lo spike E0 l&#39;ha compilato in un container e non l&#39;ha mai eseguito; senza una macchina vera la capability resta spenta.</li><li><strong>Una finestra separata</strong> — scartata: Wails gestisce una sola finestra per processo (A-03) e i pop-out restano P2; la vista figlia della stessa finestra non crea alcuna finestra.</li><li><strong>Tenere vive le schede in secondo piano</strong> — scartata dal proprietario: una vista nascosta ha i timer rallentati dal motore web (misurato nello spike E0), quindi chat e riproduzione in una scheda non attiva ne risentono; è accettato e il core non ha alcun meccanismo per evitarlo.</li><li><strong>Un campo indirizzo digitabile nella barra</strong> — scartata: salterebbe la conferma dell&#39;origine (punti 11-12).</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Chi non accende il flag non vede nulla di nuovo: nessuna voce nel ribbon né nello stato vuoto, nessuna migrazione, nessun cambio di protocollo, API o database. Chi lo accende (un amministratore, in un profilo) abilita le applicazioni <strong>sui client che hanno il browser incorporato (macOS)</strong>; altrove l&#39;applicazione si apre nel browser.</li><li>Su macOS l&#39;app porta una superficie nuova da difendere: una pagina web non fidata in un processo del sistema, nella stessa finestra. I limiti sono nei punti 26-33 e vanno detti all&#39;amministratore (guida admin) e all&#39;utente (guida utente).</li><li><strong>Limiti dichiarati:</strong> l&#39;autenticazione HTTP di base non funziona; i login con popup e <code>window.opener</code> non funzionano; un overlay minuscolo senza sfondo può passare tra i punti della sonda; il DNS rebinding non è coperto; su macOS 13 le sessioni non sono persistenti (e l&#39;app non lo segnala all&#39;utente); lo zoom dell&#39;app diverso da 100% e lo sfarfallio nel nascondere e mostrare la vista non sono verificati su WebKit.</li><li>Il codice nativo è Objective-C compilato con cgo, solo per <code>darwin</code>: la build senza cgo e gli altri sistemi hanno <code>New == nil</code>. Tre sistemi, una sola superficie provata a mano.</li><li>Le chiavi <code>webview-*</code>, la capability e le dieci voci di evento entrano nei contratti generati (<code>capabilities.gen.ts</code>, <code>events.gen.ts</code>, <code>core.gen.ts</code>).</li><li>Windows ha un driver compilato e spento (punti 34-36), Linux nessuno. Quando un driver sarà provato cambiano la lista <code>DesktopOS</code> della capability e le guide (utente e admin); il modello, i binding e il frontend restano.</li></ul><h3 id="cosa-resta-da-verificare" tabindex="-1">Cosa resta da verificare <a class="header-anchor" href="#cosa-resta-da-verificare" aria-label="Permalink to &quot;Cosa resta da verificare&quot;">​</a></h3><ul><li><strong>Nulla del frontend è verificato sulla finestra reale del desktop:</strong> il posizionamento della vista sopra l&#39;HTML, i bounds con lo zoom dell&#39;app diverso da 100% (WebKit può rispondere diversamente da Chromium), lo sfarfallio nel nascondere e mostrare, il fuoco da tastiera, la sonda <code>elementsFromPoint</code> su <code>WKWebView</code>, il trascinamento di una scheda sopra la vista. Le prove di vitest e di e2e girano sul mock dei binding (Chromium) e non vedono la vista nativa. <strong>Serve la matrice manuale</strong> <a href="./../qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a>.</li><li><strong>Nella prova del driver:</strong> tastiera e mouse reali (il processo di prova non è l&#39;applicazione attiva: gli eventi sono costruiti), camera e microfono (in quella configurazione <code>navigator.mediaDevices</code> non esiste), NTLM e certificato client, macOS precedente alla 14, il limite di viste.</li><li><strong>Windows e Linux a runtime:</strong> la capability spenta e il ripiego (scheda con «Apri nel browser») sono provati dal mock e da <code>go vet</code>, non su una macchina vera. <strong>Il driver Windows non è mai stato eseguito</strong>: è compilato per amd64 e arm64 e spento (punti 34-36); la sua matrice è la sottosezione «Driver sperimentale (interruttore)» di <a href="./../qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a>.</li><li><strong>La pulizia degli archivi orfani</strong> (punto 33) è provata dai test Go (<code>webviews_sweep_test.go</code>: driver finto, cartelle temporanee, orologio passato dal test), non su un vault eliminato davvero da un&#39;installazione in uso.</li><li><strong>Il flag resta spento di default finché la matrice non è eseguita.</strong> Per la 1.7.1 l&#39;owner ha deciso di lasciarlo spento: la matrice non è eseguita. Accenderlo di default è una decisione da prendere dopo, con i suoi esiti; il runbook <a href="./../qa/verifica-manuale-1.7.html"><code>verifica-manuale-1.7.md</code></a> propone, <strong>da confermare</strong>, di considerarlo con la sezione macOS 14 o successivo senza difetti P0 e P1.</li></ul><h3 id="sezioni-dello-spec-recepite-in-specifications-md-v1-6-2026-11-15" tabindex="-1">Sezioni dello spec (recepite in <code>Specifications.md</code> v1.6, 2026-11-15) <a class="header-anchor" href="#sezioni-dello-spec-recepite-in-specifications-md-v1-6-2026-11-15" aria-label="Permalink to &quot;Sezioni dello spec (recepite in `Specifications.md` v1.6, 2026-11-15)&quot;">​</a></h3><ul><li><strong>§2.2.1</strong>, riga «Web viewer»: da P2 a realizzato in M18/1.7.0 come «applicazioni» (file <code>.webapp</code>, vista nativa sovrapposta alla scheda; macOS con driver, Windows e Linux nel browser di sistema, workbench web in una scheda del browser); la riga «Finestre separate (pop-out)» non cambia.</li><li><strong>Appendice B</strong>, riga «Post-1.0 (P2)»: togliere «Web viewer». <strong>C.2</strong>: la riga «Web viewer in iframe bloccato da <code>X-Frame-Options</code>» passa a «mitigato da una vista nativa» (con i limiti di questo ADR); la riga «Limiti di Wails v2» resta (nessuna finestra secondaria).</li><li><strong>§2.6.6</strong>, feature flag: <code>web_viewer</code> non è più riservato; spento di default, e serve anche il browser incorporato (macOS).</li><li><strong>§3.7</strong> (sicurezza): nuova riga sulla pagina ospite (nessun ponte, nessun download né permesso, navigazione http/https validata in Go, rete privata, dati di sessione per vault fuori dal vault). La CSP non cambia (<code>frame-src &#39;none&#39;</code>).</li><li><strong>Formati del vault</strong> (§2.2 e dintorni): il file <code>.webapp</code> (<code>{&quot;version&quot;:1,&quot;url&quot;:…}</code>), per la sync di tipo <code>other</code>.</li><li><strong>§4.2:</strong> <code>internal/webview</code>, <code>internal/shell/nativeview</code>, <code>webapp/</code> del frontend e la capability <code>embeddedBrowser</code>.</li><li><strong>Appendice C.4:</strong> riga di ADR-0056. V-07/D-07 sono toccati da ADR-0051 (Wails v3.1.0), che non è accettato né recepito: questo ADR non aggiunge altro, e lo spec dice ancora Wails v2 (vedi la v1.6 di <code>Specifications.md</code>, Appendice C.4).</li><li>Nello spec v1.6 il selettore rapido (§2.2.1, riga «Quick switcher») dice che trova anche le applicazioni; il punto 9 non era nell&#39;elenco originale.</li></ul>',36)])])}const v=o(t,[["render",r]]);export{g as __pageData,v as default};
